"use client"

import Link from "next/link"
import { Button } from "@/components/ui/button"
import { ArrowRight } from "lucide-react"
import { FadeIn } from "@/components/ui/fade-in"
import { getWhatsAppUrl } from "@/lib/constants"
import { useBookingUrl } from "@/lib/use-booking-url"
import { trackLeadEvent } from "@/hooks/use-cookie-consent"
import { SiWhatsapp } from "react-icons/si"

interface IndustryCtaProps {
  trackingKey: string
  ctaLabel: string
  whatsappMessage: string
}

function pushIndustryEvent(trackingKey: string, cta: string) {
  if (typeof window !== "undefined" && window.dataLayer) {
    window.dataLayer.push({
      event: "industry_cta_click",
      industry: trackingKey,
      cta,
    })
  }
}

export function IndustryCtaButtons({ trackingKey, ctaLabel, whatsappMessage }: IndustryCtaProps) {
  const bookingUrl = useBookingUrl()

  return (
    <div className="flex flex-col items-center gap-4">
      <div className="flex flex-col sm:flex-row gap-4 justify-center">
        <Button size="lg" asChild className="gap-2 h-14 px-8 rounded-md text-base">
          <a
            href={bookingUrl}
            target="_blank"
            rel="noopener noreferrer"
            onClick={() => pushIndustryEvent(trackingKey, "booking")}
          >
            {ctaLabel}
            <ArrowRight className="w-4 h-4" />
          </a>
        </Button>
        <Button
          size="lg"
          variant="outline"
          asChild
          className="h-14 px-8 rounded-md text-base gap-2"
          id={`btn-whatsapp-${trackingKey}`}
        >
          <a
            href={getWhatsAppUrl(whatsappMessage)}
            target="_blank"
            rel="noopener noreferrer"
            onClick={() => {
              pushIndustryEvent(trackingKey, "whatsapp")
              trackLeadEvent({ source: `industry_${trackingKey}_whatsapp` })
            }}
          >
            <SiWhatsapp aria-hidden="true" className="h-4 w-4 text-[#25D366]" />
            WhatsApp Us
          </a>
        </Button>
      </div>
      <Link
        href="/pricing"
        className="text-sm text-muted-foreground underline-offset-4 transition-colors hover:text-primary hover:underline"
      >
        See pilot pricing
      </Link>
    </div>
  )
}

export function IndustryCtaCard({ trackingKey, ctaLabel, whatsappMessage }: IndustryCtaProps) {
  return (
    <FadeIn>
      <div className="bg-primary/5 border border-primary/10 rounded-lg p-8 md:p-14 text-center max-w-4xl mx-auto">
        <h2 className="text-3xl font-bold mb-6">Start with one contained pilot</h2>
        <p className="text-lg text-muted-foreground mb-8 max-w-2xl mx-auto">
          One intake, one approval workflow, one destination system. Tell us how the work
          moves through your team today, and we will tell you honestly whether this workflow fits.
        </p>
        <IndustryCtaButtons
          trackingKey={trackingKey}
          ctaLabel={ctaLabel}
          whatsappMessage={whatsappMessage}
        />
      </div>
    </FadeIn>
  )
}
